import type { AppHash, SpecHash, SpecId } from '../spec/index.js'
import type { GeneratedStamp } from './records.js'

/**
 * Sole owner of the generated-file header format. Written by `writeGenerated`, read by
 * `staleness`, the reporter, and `fix`.
 *
 *   // GENERATED by libretto from specs/auth/login.md (hash: 9f2c1a…)
 *   // DO NOT EDIT. Edit the spec and run `libretto generate`.
 *   // libretto: {"spec":"auth/login","specHash":"9f2c…","appHash":"c0de…","bodyHash":"41ab…"}
 *
 * Lines 1–2 are SPEC's human header. Line 3 is the machine stamp. `bodyHash` covers
 * everything after the header, so a hand edit is detectable without a second manifest.
 * `appHash` is `app.md` at generation time, so an `app.md` edit is visible per file.
 */
export interface Header extends GeneratedStamp {
  readonly spec: SpecId
}

export function renderHeader(spec: SpecId, specFile: string, specHash: SpecHash, appHash: AppHash, body: string): string {
  throw new Error('not implemented')
}

/** `null` if the file has no valid header (treated as hand-written: `generate` overwrites with a warning). */
export function parseHeader(fileText: string): { header: Header; body: string } | null {
  throw new Error('not implemented')
}
